// Manually authored: not generated by sqlc. sqlc v1.30 doesn't natively
// support UNNEST array-batch upserts cleanly for jsonb[]; this file uses the
// same package-private DBTX handle and Scan loop layout as the generated
// task_dag_node_write.sql.go to keep the surface uniform.

package sqlc

import (
	"context"
)

// BatchUpsertTaskDagNodesParams holds equal-length slices forming the columns
// of a multi-row INSERT … ON CONFLICT … DO UPDATE on task_dag_nodes. Caller
// must ensure all 8 slices have the same length; mismatched lengths cause PG
// to error at parameter bind time.
type BatchUpsertTaskDagNodesParams struct {
	DagKeys     []string `json:"dag_keys"`
	NodeKeys    []string `json:"node_keys"`
	Titles      []string `json:"titles"`
	NodeTypes   []string `json:"node_types"`
	AssignedTos []string `json:"assigned_tos"`
	DependsOns  [][]byte `json:"depends_ons"` // jsonb[]; each element raw JSON bytes
	CommandRefs []string `json:"command_refs"`
	Configs     [][]byte `json:"configs"` // jsonb[]; each element raw JSON bytes
}

// batchUpsertTaskDagNodes is a single multi-row INSERT … ON CONFLICT statement
// that does the equivalent of N UpsertTaskDagNode calls in 1 round-trip.
// UNNEST aligns the 8 array params element-wise; ON CONFLICT targets the
// template-node partial unique index from migration 0089.
//
// Casts ($6::jsonb[], $8::jsonb[]) match UpsertTaskDagNode's $6::jsonb /
// $8::jsonb (jsonb[] is the array form). The text[] casts on $1..$5,$7 are
// explicit so pgx encodes []string deterministically as text[].
const batchUpsertTaskDagNodes = `-- name: BatchUpsertTaskDagNodes :exec
INSERT INTO task_dag_nodes (dag_key, node_key, title, node_type, assigned_to, depends_on, command_ref, config)
SELECT * FROM UNNEST(
    $1::text[],
    $2::text[],
    $3::text[],
    $4::text[],
    $5::text[],
    $6::jsonb[],
    $7::text[],
    $8::jsonb[]
)
ON CONFLICT (dag_key, node_key) WHERE run_id IS NULL DO UPDATE
SET title = EXCLUDED.title,
    node_type = EXCLUDED.node_type,
    assigned_to = EXCLUDED.assigned_to,
    depends_on = EXCLUDED.depends_on,
    command_ref = EXCLUDED.command_ref,
    config = EXCLUDED.config,
    updated_at = NOW()
`

// BatchUpsertTaskDagNodes executes the multi-row UPSERT in 1 PG round-trip.
// Returns the affected row count from PG's CommandTag (insert + update rows
// both count). Empty input is a no-op returning (0, nil) to keep callers
// from special-casing nil/empty slices.
func (q *Queries) BatchUpsertTaskDagNodes(ctx context.Context, arg BatchUpsertTaskDagNodesParams) (int64, error) {
	if len(arg.DagKeys) == 0 {
		return 0, nil
	}
	tag, err := q.db.Exec(ctx, batchUpsertTaskDagNodes,
		arg.DagKeys,
		arg.NodeKeys,
		arg.Titles,
		arg.NodeTypes,
		arg.AssignedTos,
		arg.DependsOns,
		arg.CommandRefs,
		arg.Configs,
	)
	if err != nil {
		return 0, err
	}
	return tag.RowsAffected(), nil
}
